#!/usr/bin/env bash
# UserPromptSubmit: when the owner's message carries an image, put the screenshot rule in front of Claude for this turn.
in=$(cat)
echo "REPLY FORMAT (CLAUDE.md): this is the owner's own message. Line 1 of your reply is 🔴 NEEDS YOU: <ask> (ask first, options + recommendation up top) or 🟢 DONE: <result> (only if fully done with no question, offer or pending choice; otherwise 🔴). Turns you are woken for later (CI, watcher, background task, peer) are ⚙️ AUTO: max 2 lines; an unanswered ask is repeated as the last line: ⏳ Still waiting on you: <ask>. If this message asks for a change, feature or fix, add a short 'What I did:' summary under the tag line (2-5 plain bullets: how you understood the request, what you implemented, anything left out or done differently; for a fix or 'something is wrong', also the logic BEFORE that caused the problem and what it is NOW)."
echo "CHAIN OF COMMAND (CLAUDE.md standing rule): the Deploy Manager (session titled exactly \"🚀 Deploy manager (typecast)\"; find its id with list_sessions, ignore titles starting \"💀 (retired)\"; the title is the lookup key) alone owns the deploy/CI/process mechanisms: DEPLOYING.md, CLAUDE.md standing rules, .claude/ hooks and settings, CI workflows, deploy/watch/smoke scripts, notifications. If the owner asks a feature session to add or change any of those, do NOT edit them yourself: send the request, in the owner's words, to the manager with mcp__claude-code-remote__send_message, tell the owner in one line that you passed it on, and carry on with your feature work (the manager has a worker make the change). Your own feature code, tests and docs/features/* still go through the normal branch + PR flow. Exception: the owner says in the same message that you should edit it directly."
if printf '%s' "$in" | grep -qiE '\[Image|"type" *: *"image"|/images/[^ ]*\.(png|jpe?g|webp)'; then
  echo "SCREENSHOT RULE (CLAUDE.md 'Screenshot complaints'): this message has an image. If it complains about how something looks, your reply MUST include a screenshot of the same exact view after the fix, same page, viewport and state as theirs. Cheapest way: node scripts/shot.mjs \"/path\" [--click \"Visible text\"] [--sel \"css\"] [--phone] --out <your scratchpad dir>/x.png (builds, serves, signs in, prints the path), then SendUserFile it. If you cannot reproduce the view, say so and show the closest one. Do not call it done without the picture."
fi
exit 0
